// called on the UI thread: a scheduler over its SynchronizationContext
var ui = TaskScheduler.FromCurrentSynchronizationContext();

LoadAsync().ContinueWith(t =>
{
    status.Text = "Working…";         // fine: the continuation runs on ui
    t.ContinueWith(_ => Heavy());      // no scheduler → Current == ui
}, ui);                                //   → Heavy() on the UI thread, window hangs

// StartNew: delegate, token, options, scheduler
Task.Factory.StartNew(() => Heavy(), CancellationToken.None,
    TaskCreationOptions.None, TaskScheduler.Default);   // explicitly to the pool

