var cts = new CancellationTokenSource();
Task<Data> load = LoadAsync();

var eager = load.ContinueWith(t => Use(t.Result), cts.Token);
var lazy = load.ContinueWith(t => Use(t.Result), cts.Token,
    TaskContinuationOptions.LazyCancellation, TaskScheduler.Default);

cts.Cancel();
// eager — Canceled at once, although load is still running
// lazy  — Canceled only when load completes
